/** The ZhaoHua sandbox settings card: summary row + full detail card. */

import { useCallback, useEffect, useState } from 'react'
import type { PropsLocale, PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'
import { en, zh, type SandboxLocaleKey } from './locales.ts'

/** Props the renderer binds for the sandbox page. */
export type SandboxCardProps =
  PropsRuntime<'plugins.item'>
  & PropsLocale<'zhbox'>

interface StatusShape {
  toggle?: string
  rootfsReady?: boolean
  prootVersion?: string
}

/** Locale copy for the summary one-liner, computed from live state. */
function summaryText(
  status: StatusShape | null,
  dict: Record<'summaryOn' | 'summaryOff' | 'summaryNoRootfs', string>,
): string {
  const toggle = status?.toggle === 'on'
    ? dict.summaryOn
    : dict.summaryOff
  return status?.rootfsReady === true ? toggle : `${toggle} · ${dict.summaryNoRootfs}`
}

/**
 * Render the sandbox entry. The Plugins page asks for the one-liner
 * (`view === 'summary'`) and the full card separately; the summary reflects
 * the live toggle state so the list row reads at a glance.
 */
export function SandboxCard(props: SandboxCardProps) {
  const t = props.t as (key: SandboxLocaleKey | 'summaryOn' | 'summaryOff' | 'summaryNoRootfs') => string
  const [status, setStatus] = useState<StatusShape | null>(null)
  const [busy, setBusy] = useState<'' | 'toggle' | 'install' | 'test' | 'gorust'>('')
  const [output, setOutput] = useState('')
  const [error, setError] = useState('')

  const refresh = useCallback(async (): Promise<void> => {
    try {
      const res = await fetch('/api/zhbox/status')
      const body = await res.json() as Record<string, unknown>
      if (res.ok) setStatus(body as StatusShape)
    } catch { /* best-effort; action errors surface in the output pane */ }
  }, [])

  // Load once on mount; also re-check whenever an action completes.
  useEffect(() => { void refresh() }, [refresh])
  // Re-check when the page becomes visible again (list -> detail navigation),
  // so the summary row never disagrees with the detail card.
  useEffect(() => {
    const onVis = (): void => { if (document.visibilityState === 'visible') void refresh() }
    document.addEventListener('visibilitychange', onVis)
    return () => document.removeEventListener('visibilitychange', onVis)
  }, [refresh])

  const post = async (action: 'toggle' | 'install' | 'test'): Promise<void> => {
    setBusy(action)
    setError('')
    try {
      const res = await fetch(`/api/zhbox/${action}`, { method: 'POST' })
      const body = await res.json() as Record<string, unknown>
      if (!res.ok) throw new Error(String(body.error ?? res.status))
      if (action === 'toggle') setStatus(s => ({ ...(s ?? {}), toggle: String(body.toggle ?? 'off') }))
      else setOutput(String(body.output ?? ''))
      await refresh()
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e))
    }
    setBusy('')
  }

  // Summary view: the Plugins list row — title + description come from the
  // page chrome; this returns just the live-state one-liner.
  if (props.view === 'summary') {
    const dict: Record<'summaryOn' | 'summaryOff' | 'summaryNoRootfs', string> =
      (props as { lang?: string }).lang === 'en'
        ? {
            summaryOn: 'Sandbox on — all commands run inside',
            summaryOff: 'Sandbox off — toolchain commands only',
            summaryNoRootfs: 'rootfs not extracted',
          }
        : {
            summaryOn: '沙箱开 — 全部命令进沙箱',
            summaryOff: '沙箱关 — 仅工具链命令进沙箱',
            summaryNoRootfs: 'rootfs 未解包',
          }
    return <>{summaryText(status, dict)}</>
  }

  const postGorust = async (): Promise<void> => {
    setBusy('gorust')
    setError('')
    setOutput(t('installingGo'))
    try {
      const res = await fetch('/api/zhbox/gorust', { method: 'POST' })
      const body = await res.json() as Record<string, unknown>
      if (!res.ok) throw new Error(String(body.error ?? res.status))
      setOutput(String(body.output ?? ''))
      await refresh()
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e))
    }
    setBusy('')
  }

  const button = (label: string, action: string, onClick: () => void, primary = false): React.ReactElement =>
    (
      <button
        key={label}
        type="button"
        onClick={onClick}
        disabled={busy !== ''}
        style={{
          padding: '8px 14px', borderRadius: 8, fontSize: 13,
          border: primary ? 'none' : '1px solid var(--dsh-border, #8884)',
          background: primary ? 'var(--dsh-accent, #4c7dff)' : 'transparent',
          color: primary ? '#fff' : 'var(--dsh-ink, inherit)',
          cursor: busy === '' ? 'pointer' : 'not-allowed',
          opacity: busy === '' ? 1 : 0.6,
        }}
      >
        {busy === action ? '…' : label}
      </button>
    )

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 12, padding: '4px 0' }}>
      <div style={{ fontSize: 13, lineHeight: 1.7 }}>
        <div>
          {t('status')}: <strong>{status?.toggle === 'on' ? t('toggleOn') : t('toggleOff')}</strong>
        </div>
        <div>{status?.rootfsReady === true ? `✓ ${t('rootfsReady')}` : t('rootfsMissing')}</div>
        {error !== '' && <div style={{ color: 'var(--dsh-red, #d33)' }}>{t('failed')}: {error}</div>}
      </div>

      <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap' }}>
        {button(t('toggle'), 'toggle', () => { void post('toggle') })}
        {button(t('install'), 'install', () => { void post('install') }, true)}
        {button(t('gorust'), 'gorust', () => { void postGorust() })}
        {button(t('test'), 'test', () => { void post('test') })}
      </div>

      {output !== '' && (
        <pre style={{
          margin: 0, padding: 10, borderRadius: 8, fontSize: 12,
          background: 'var(--dsh-bg-2, #8881)', maxHeight: 240, overflow: 'auto',
          whiteSpace: 'pre-wrap', wordBreak: 'break-all',
        }}>{output}</pre>
      )}
    </div>
  )
}
